var torus = scene.getObjectByName( 'Torus' );
scene.remove( torus );

var map = torus.material.emissiveMap;
map.wrapS = THREE.RepeatWrapping;
map.repeat.x = 2;
map.encoding = THREE.sRGBEncoding;

//

var group = new THREE.Group();
scene.add( group );

for ( var i = 0; i < 11; i ++ ) {

	var clone = torus.clone();
	clone.geometry = new THREE.TorusGeometry( i * 10 + 20, 5, 32, 64 );
	clone.material = torus.material.clone();
	group.add( clone );

}

function update( event ) {

	var time = 0.4 + event.time * 0.0003;

	camera.position.x = Math.cos( time ) * 200;
	camera.position.z = Math.sin( time ) * 200;
	camera.lookAt( new THREE.Vector3() );

	var children = group.children;

	for ( var i = 0; i < children.length; i ++ ) {

		var child = children[ i ];

		child.position.x = Math.sin( time - i * 0.15 ) * 50;
		child.position.y = Math.sin( time * 1.3 - i * 0.15 ) * 50;
		child.rotation.x = time * 2.123 - Math.pow( i, 1.15 ) * 0.13;
		child.rotation.y = time * 2.85 - Math.pow( i, 1.15 ) * 0.13;
		child.material.emissive.r = Math.max( 0, Math.sin( - time * 5 + i * 0.2 ) ) * 0.5;
		child.material.emissive.b = Math.pow( child.material.emissive.r * 2, 6 );
		child.material.emissiveIntensity = 2.0;

	}

}

var envScene = new THREE.Scene();

var geometry = new THREE.IcosahedronBufferGeometry( 20, 4 );
var material = new THREE.MeshStandardMaterial( { metalness: 0, side: THREE.BackSide } );
var mesh = new THREE.Mesh( geometry, material );
envScene.add( mesh );

var geometry = new THREE.CircleBufferGeometry( 6, 64 );
var material = new THREE.MeshLambertMaterial( {
	color: 0x000000, emissive: 0xaabbff, emissiveIntensity: 0.5
} );

var mesh = new THREE.Mesh( geometry, material );
mesh.position.set( 0, 4, 0 );
mesh.rotation.x = Math.PI / 2;
envScene.add( mesh );

var material = new THREE.MeshLambertMaterial( {
	color: 0x000000, emissive: 0x8888ff, emissiveIntensity: 0.15
} );

var mesh = new THREE.Mesh( geometry, material );
mesh.position.set( 0, - 4, 0 );
mesh.rotation.x = - Math.PI / 2;
envScene.add( mesh );

var pmremGenerator = new THREE.PMREMGenerator( renderer );
var renderTarget = pmremGenerator.fromScene( envScene );

scene.environment = renderTarget.texture;
